def __str__(self):
    ret = getattr(self, '_line', None)
    if ret is not None:
        return ret
    try:
        linecache.checkcache(self.filename)
        mod_globals = {'__name__': self._mod_name,
                       '__loader__': self._mod_loader}
        line = linecache.getline(self.filename,
                                 self.lineno,
                                 mod_globals)
        line = line.rstrip()
    except KeyError:
        line = ''
    self._line = line
    return line

